<template>
  <el-container>
    <el-header class="app-header"><AsideVue/></el-header>
    <el-main class="main-ctx monitor-page">
      <div class="page-heading">
        <div><h2>学生慕课学习监测</h2><p>汇总学习时长与视频行为分析结果，专注度低于 40 分标记为疑似走神。</p></div>
        <el-button :loading="loading" @click="load"><el-icon><Refresh/></el-icon>刷新数据</el-button>
      </div>

      <el-row :gutter="16" class="summary-row">
        <el-col :span="6"><el-card shadow="never"><div class="metric"><el-icon color="#2f80ed"><User/></el-icon><div><span>学习学生</span><strong>{{ summary.student_count || 0 }}</strong></div></div></el-card></el-col>
        <el-col :span="6"><el-card shadow="never"><div class="metric"><el-icon color="#16a085"><Clock/></el-icon><div><span>累计学习时长</span><strong>{{ formatDuration(summary.total_duration) }}</strong></div></div></el-card></el-col>
        <el-col :span="6"><el-card shadow="never"><div class="metric"><el-icon color="#8e6ad8"><DataAnalysis/></el-icon><div><span>平均专注度</span><strong>{{ summary.avg_attention || 0 }} 分</strong></div></div></el-card></el-col>
        <el-col :span="6"><el-card shadow="never"><div class="metric"><el-icon color="#e67e22"><Warning/></el-icon><div><span>走神片段</span><strong>{{ summary.distracted_count || 0 }}</strong></div></div></el-card></el-col>
      </el-row>

      <el-card shadow="never">
        <el-form :model="query" inline>
          <el-form-item label="学生账号"><el-input v-model="query.username" clearable placeholder="输入姓名或账号"/></el-form-item>
          <el-form-item label="章节"><el-input v-model="query.chapter" clearable placeholder="例如：1"/></el-form-item>
          <el-form-item><el-button type="primary" @click="search">查询</el-button><el-button @click="reset">重置</el-button></el-form-item>
        </el-form>
        <el-table :data="rows" border stripe v-loading="loading">
          <el-table-column prop="username" label="学生" min-width="120"/>
          <el-table-column label="学习内容" min-width="180"><template #default="s">第 {{ s.row.chapter }} 章 · {{ s.row.subchapter }}</template></el-table-column>
          <el-table-column label="学习时长" width="130"><template #default="s"><strong>{{ formatDuration(s.row.learning_duration) }}</strong></template></el-table-column>
          <el-table-column label="平均专注度" width="190">
            <template #default="s"><el-progress :percentage="Math.round(Number(s.row.attention_score || 0))" :status="Number(s.row.attention_score)<40?'exception':undefined"/></template>
          </el-table-column>
          <el-table-column label="视频行为结果" width="140" align="center">
            <template #default="s"><el-tag :type="s.row.is_distracted?'danger':'success'">{{ s.row.behavior_label }}</el-tag></template>
          </el-table-column>
          <el-table-column label="走神/采样" width="110" align="center"><template #default="s">{{ s.row.distracted_samples }}/{{ s.row.sample_count }}</template></el-table-column>
          <el-table-column prop="last_learning_time" label="最近学习" min-width="170"/>
        </el-table>
        <el-pagination class="pagination" v-model:current-page="query.pageNum" v-model:page-size="query.pageSize" :total="total" layout="total, sizes, prev, pager, next" @change="load"/>
      </el-card>
    </el-main>
  </el-container>
</template>

<script>
import axios from 'axios'
import AsideVue from '@/components/AsideVue.vue'
export default {
  name:'LearningMonitor',components:{AsideVue},
  data:()=>({loading:false,rows:[],total:0,summary:{},query:{username:'',chapter:'',pageNum:1,pageSize:20}}),
  created(){this.load()},
  methods:{
    async load(){this.loading=true;try{const {data}=await axios.get('/api/learning/monitor',{params:this.query});this.rows=data.rows||[];this.total=data.total||0;this.summary=data.summary||{}}catch(e){this.$message.error(e.response?.data?.message||'学习监测数据加载失败')}finally{this.loading=false}},
    search(){this.query.pageNum=1;this.load()},reset(){this.query={username:'',chapter:'',pageNum:1,pageSize:20};this.load()},
    formatDuration(value){const total=Math.max(0,Number(value)||0);const h=Math.floor(total/3600);const m=Math.floor(total%3600/60);if(h)return `${h}小时${m}分钟`;if(m)return `${m}分钟`;return `${Math.round(total)}秒`}
  }
}
</script>

<style scoped>
.app-header{margin-top:4px;padding:0}.monitor-page{background:#f5f7fb}.page-heading{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px}.page-heading h2{margin:0;color:#26384d}.page-heading p{margin:6px 0 0;color:#8290a3;font-size:13px}.summary-row{margin-bottom:16px}.metric{display:flex;align-items:center;gap:14px}.metric>.el-icon{font-size:34px}.metric span,.metric strong{display:block}.metric span{font-size:13px;color:#8a98aa}.metric strong{font-size:22px;color:#26384d;margin-top:5px}.pagination{margin-top:18px;justify-content:flex-end}
</style>
